import {advisoryButton} from './corridor-advisory.mjs';
import {money,dateLabel,STRESS_PRESETS} from './model.mjs';
import {scenarioImpact} from './scenario-impact.mjs';
import {mapReference} from './planner-model.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=n=>`${n>0?'+':n<0?'−':''}${Math.abs(n)}`;
const change=n=>`${n>0?'+':n<0?'−':''}${money(Math.abs(n))}`;
export function scenarioLabView(settings,icon,costOpen=false) {
 const impact=scenarioImpact(settings),r=impact.after,best=impact.best,ref=mapReference(settings);
 const preset=STRESS_PRESETS.find(p=>p.fuel===settings.fuel&&p.delay===settings.delay);
 const control=(key,label,unit,min,max,help)=>`<div class="scenario-control" data-control="${key}"><div class="scenario-control-heading"><label for="scenario-${key}">${label}</label><div class="scenario-inline-value"><input id="scenario-${key}" data-assumption-number="${key}" data-focus="${key}-number" type="number" min="${min}" max="${max}" step="1" value="${settings[key]}" aria-label="${label}"><span>${unit}</span></div></div><input class="scenario-range" type="range" min="${min}" max="${max}" step="1" data-assumption="${key}" data-focus="${key}-range" aria-label="${key==='fuel'?'Fuel surcharge percentage':'Additional port delay in days'}" value="${settings[key]}"><p class="scenario-control-help">${help}</p></div>`;
 const violations=[...(r.cost>settings.budget?[`${money(r.cost-settings.budget)} over budget`]:[]),...(r.buffer<0?[`${-r.buffer} days late · Due ${dateLabel(settings.deadline)}`]:[]),...(r.co2>settings.emissions?[`${(r.co2-settings.emissions).toFixed(1)} t above emissions limit`]:[])];
 return `<aside class="detail-panel planning-panel panel" aria-label="Route planning panel"><header class="planning-header"><span>SELECTED ROUTE ${r.id===settings.baseline?'· BASELINE':''}</span><button class="text-button" data-action="itinerary">Details ${icon('arrow',14)}</button></header><section class="planning-selection"><h2>${esc(r.short)}</h2><div class="planning-key-metrics"><div><span>Total logistics cost</span><strong data-metric="cost" data-value="${r.cost}">${money(r.cost)}</strong></div><div><span>Estimated arrival</span><strong>${dateLabel(r.arrival)}</strong></div></div><p class="planning-secondary-metrics"><span>${icon('clock',14)} ${r.days} days</span><span>${icon('leaf',14)} ${r.co2.toFixed(1)} t CO₂e <small>±${r.uncertainty}%</small></span></p><div class="planning-verdict ${r.feasible?'is-valid':'is-invalid'}">${icon(r.feasible?'check':'alert',16)}<div>${r.feasible?`Within all limits <span>· ${r.buffer?`${r.buffer} days to spare`:'On deadline'}</span>`:violations.map(v=>`<span>${v}</span>`).join('')}</div></div>${r.id==='seaair'?`<div class="planning-advisory">${advisoryButton(icon,true)}<span>Source update · 6 Nov 2026</span></div>`:''}</section><section class="decision-summary" aria-label="Planning recommendation"><button class="decision-count" data-action="focus-eligible" aria-label="View routes within planning limits"><strong>${impact.eligibleAfter}<small>/6</small></strong><span>Routes within limits ${icon('arrow',13)}</span></button><div class="decision-recommendation"><strong>${best?best.id===r.id?'Best fit for your priority':esc(best.short):'No route meets every limit'}</strong><p>${best?best.id===r.id?'The selected route leads the eligible group.':`${change(best.cost-r.cost)} · ${best.days<r.days?`${r.days-best.days} days earlier`:best.days>r.days?`${best.days-r.days} days later`:'Same transit'} vs selected`:'Review the limits or change the assumptions.'}</p>${best&&best.id!==r.id?`<button class="button primary full" data-action="select" data-value="${best.id}">Inspect alternative ${icon('arrow',15)}</button>`:best?`<button class="text-button" data-action="explain-ranking">Why this route? ${icon('arrow',14)}</button>`:`<button class="button outline full" data-action="constraints">Review planning limits ${icon('arrow',15)}</button>`}</div></section><section class="scenario-workbench" id="scenario-lab" aria-labelledby="scenario-lab-title"><div class="scenario-lab-heading"><h2 id="scenario-lab-title">Scenario lab</h2><button class="text-button" data-action="stress-preset" data-value="base" ${impact.changed?'':'disabled'}>Reset</button></div><div class="scenario-preset-label"><span id="scenario-preset-label">Quick test</span><button class="preset-trigger" type="button" data-action="preset-menu" data-value="${preset?.id||'custom'}" data-focus="scenario-preset" aria-label="Scenario preset: ${preset?.label||'Custom assumptions'}" aria-haspopup="listbox" aria-expanded="false" aria-controls="scenario-preset-menu"><span>${preset?.label||'Custom assumptions'}</span>${icon('down',16)}</button></div><div class="scenario-inputs">${control('fuel','Fuel adjustment','%',-20,40,'Freight cost only · −20% to +40%')}${control('delay','Port delay','days',0,14,'Ocean, rail & sea–air · 0–14 days')}</div><section class="scenario-impact" aria-label="Impact of this scenario" ${impact.changed?'':'hidden'}><div class="impact-heading"><strong>Change from base assumptions</strong></div><dl><div><dt>Cost</dt><dd class="${impact.costChange>0?'caution':impact.costChange<0?'good':''}">${change(impact.costChange)}</dd></div><div><dt>Transit</dt><dd class="${impact.daysChange>0?'caution':''}">${signed(impact.daysChange)} <span>days</span></dd></div>${impact.daysChange?`<div class="impact-arrival"><dt>Arrival</dt><dd><span>${dateLabel(impact.before.arrival)}</span>${icon('arrow',13)}<strong>${dateLabel(r.arrival)}</strong></dd></div>`:''}</dl></section></section><div class="planning-secondary"><details class="planning-costs" data-cost-details ${costOpen?'open':''}><summary>Cost breakdown ${icon('down',15)}</summary><dl class="cost-breakdown"><div><dt>Freight${settings.fuel?` (${signed(settings.fuel)}%)`:''}</dt><dd>${money(r.freight+r.surcharge)}</dd></div><div><dt>Origin & destination</dt><dd>${money(r.origin+r.destination)}</dd></div><div><dt>Cargo insurance</dt><dd>${money(r.insurance)}</dd></div><div><dt>Contingency</dt><dd>${money(r.reserve)}</dd></div></dl><button class="text-button" data-action="methodology">About these estimates ${icon('info',14)}</button></details><button class="button outline full compare-baseline" data-action="compare-baseline">${icon('compare',16)} ${ref.label==='Baseline'?'Compare with baseline':'Compare with alternative'}</button></div></aside>`;
}
